{
  "outcome": "escalate",
  "rationale": "This claim is escalated because automated findings indicate it is unclear whether an exclusion applies due to disputed facts regarding the collision. Section 6.2 governs this situation and requires escalation when material facts are open to more than one reasonable reading.",
  "citations": [
    {
      "clause_id": "STD-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
